/// Combines the callback-free local prefix of prototype lookup. A virtual
/// descriptor or Super keeps the original getter path. Otherwise the same
/// descriptor supplies the stored value, or the same native display
/// fallback used by get_local_stored runs after an absent/hidden slot.
/// Keep the read borrow through that fallback, just as get_local_stored
/// does; never carry a descriptor or native result across a callback.
pub(crate) fn boxhead_lookup_property(
    self,
    name: AvmString<'gc>,
    activation: &mut Activation<'_, 'gc>,
) -> super::BoxheadLookupProperty<'gc> {
    let read = self.0.borrow();
    if matches!(read.native, NativeObject::Super(_)) {
        return super::BoxheadLookupProperty::Slow;
    }
    if let Some(property) = read.properties
        .get_avm(name, activation.is_case_sensitive())
        .filter(|property| property.allow_swf_version(activation.swf_version()))
    {
        return if property.is_virtual() {
            super::BoxheadLookupProperty::Slow
        } else {
            super::BoxheadLookupProperty::Resolved(property.data())
        };
    }
    match read.native.as_display_object()
        .and_then(|dobj| stage_object::get_property(dobj, name, activation))
    {
        Some(value) => super::BoxheadLookupProperty::Resolved(value),
        None => super::BoxheadLookupProperty::Missing,
    }
